    if (old waitCount >= waitLimit && path 있음) { u = normalize(path[0] - holdPos) * (1,0,0,0); if |((barR.x - 2.5) - holdPos.x) * u.x| > 1.0 : waitCount = 0 }
    d = holdPos - pos; return |d| < 0.3 ? 0 : d }
  if (barR.x - prevR.x > -0.02) {  // 앞 벽이 다가오지 않음
    if (stuckCount >= 1) { stuckCount = 0; stuckLimit = SyncRandRange(10, 20) }
    while (path 있음) { d = path[0] - pos; d.y = 0
      if (path[1] 있음) { s = normalize(path[1]-path[0]); t = dot(-d, s); if (t <= 0.1 && |d - s*t| < 0.5) { path.shift(); continue } }
      if (|d| >= 0.3) break-to-target; path.shift() }
    if (path 비었음) return 0
    target: if (pos.x > barR.x - 2.5) { waitCount = 1; waitLimit = SyncRandRange(10, 30); holdPos = pos }
            else if (pos.x > cam.worldX + 9) { waitCount = 1; waitLimit = SyncRandRange(20, 80); holdPos = pos }
    return d
  } else {  // 앞 벽이 0.02 넘게 다가옴 → 후퇴
    if (history 비었음) return 0; if (++stuckCount < stuckLimit) return 0
    for (k = n-1; k >= 1; k--) { d = history[k] - pos; d.y = 0; if (|d| >= 0.3) return d; history.resize(k) }
    return 0 }
상수: 0.02, 2.5, 9.0, 0.3, 0.5, 0.1, 0.25, 10, 12개(0xC0 B)

